import { Component } from 'react'
import { connect } from 'react-redux'
import PropTypes from 'prop-types'
import { AdiraPkgDetailsStyle } from './index.style'
import Expand from '../../../components/Expand'
import { LANG_STRINGS } from '../../../lang'
import { ImageUrl, BENEFIT, GOOGLE_DOC } from '../../../images'
import { BottomActionContainerStyle, Row } from '../../../commonStyle/index.style'
import { Button, CustomText, TermsCondition } from '../../../components'
import { AgentColorPallette } from '../../../configs/colorPallete'
import { formatMoney } from '../../../helpers/utility'
import PkgHeader from './components/PkgHeader'
import policyActions from '../../../redux/policy/action'
import { ADIRA_BIKE_PROTECTION_LITE } from '../../../constants/pkgCode'
import CircularLoader from '../../../components/CircularLoader'
import { get } from 'lodash/object'
import { setToLocalStorage } from '../../../helpers/localstorage'
import { POLICY_PKG_DATA } from '../../../constants/cookies'

const { getPackageDetail } = policyActions
class AdiraPackageDetails extends Component {
  static propTypes = {
    btnText: PropTypes.string,
    onInsuranceBtnClick: PropTypes.func
  }

  constructor (props) {
    super(props)
    this.state = {
      expand: 'benefit'
    }
  }

  componentDidMount () {
    this.props.getPackageDetail({
      body: {},
      packageCode: ADIRA_BIKE_PROTECTION_LITE
    })
  }

  handleOnExpand = (expandKey) => {
    // this function used to update the expand key
    this.setState(prevState => ({
      expand: prevState.expand === expandKey ? '' : expandKey // if click on the same tab then empty the expand
    }))
  }

  handleBuy = () => {
    setToLocalStorage(POLICY_PKG_DATA, this.props.packageDetail)
    this.props.onInsuranceBtnClick()
  }

  getBenefitContainer = (benefit, index) => {
    return (
      <div className='benefit-content' key={`benefit_${index}`}>
        <CustomText
          size='13px'
          color={AgentColorPallette.black}
          weight={800}
          bottom='8px'
        >
          {index + 1}.&nbsp;{benefit.title}
        </CustomText>
        <CustomText color={AgentColorPallette.fontSecondary} bottom='5px'>
          {benefit.description}
        </CustomText>
        <CustomText size='13px' color={AgentColorPallette.mustard} weight={700}>
          {LANG_STRINGS.benefitUpTo}&nbsp;{benefit.sum_insured}
        </CustomText>
      </div>
    )
  }

  getClaimContainer = (title, content) => {
    return (
      <div className='benefit-content'>
        <CustomText color={AgentColorPallette.black} weight={800} bottom='6px'>
          {title}
        </CustomText>
        <CustomText color={AgentColorPallette.black}>
          {content}
        </CustomText>
      </div>
    )
  }

  render () {
    const { expand } = this.state
    const { btnText, packageDetailLoading, packageDetail } = this.props
    const { benefit = {}, tnc = {} } = packageDetail

    return (
      <CircularLoader isLoading={packageDetailLoading}>
        <AdiraPkgDetailsStyle>
          <PkgHeader />
          <div className='body-content'>
            <Expand
              title={LANG_STRINGS.benefit}
              imgUrl={BENEFIT}
              expand={expand === 'benefit'}
              key='benefit'
              headerColor={AgentColorPallette.lightBlue}
              titleColor={AgentColorPallette.white}
              onExpand={() => this.handleOnExpand('benefit')}
            >
              <div>
                {
                  !!get(benefit, 'data.length', 0) && benefit.data.map((item, index) => (
                    this.getBenefitContainer(item, index)
                  ))
                }
              </div>
            </Expand>
            <Expand
              title={LANG_STRINGS.termsConditions}
              imgUrl={GOOGLE_DOC}
              expand={expand === 'terms'}
              headerColor={AgentColorPallette.lightBlue}
              titleColor={AgentColorPallette.white}
              key='terms'
              onExpand={() => this.handleOnExpand('terms')}
            >
              <div className='benefit-content'>
                {
                  !!get(tnc, 'data.length', 0) && (
                    <TermsCondition termsData={tnc.data} className='terms-content' />
                  )
                }
              </div>
            </Expand>
            <Expand
              title={LANG_STRINGS.claim}
              imgUrl={ImageUrl.moneyBagIcon}
              expand={expand === 'claim'}
              key='claim'
              headerColor={AgentColorPallette.lightBlue}
              titleColor={AgentColorPallette.white}
              onExpand={() => this.handleOnExpand('claim')}
            >
              <div>
                {
                  this.getClaimContainer(
                    '1. Siapkan dokumen yang diperlukan.',
                    'Untuk proses klaim yang mudah, harap siapkan dokumen yang diperlukan seperti KTP, surat pernyataan, atau lainnya.'
                  )
                }
                {
                  this.getClaimContainer(
                    '2. Kunjungi Portal Klaim.',
                    'Kunjungi https://policies.pasarpolis.io/ dan otentikasi nomor telepon Anda melalui OTP.'
                  )
                }
                {
                  this.getClaimContainer(
                    '3. Isi formulir dan unggah dokumen Anda.',
                    'Ikuti langkah dan unggah dokumen Anda.'
                  )
                }
              </div>
            </Expand>
          </div>
          <BottomActionContainerStyle justify='start' align='start' padding='0'>
            <Row align='center' justify='space-between' className='action-container'>
              <div>
                <CustomText weight={800} color={AgentColorPallette.fontSecondary}>{LANG_STRINGS.premiumPrice}</CustomText>
                <CustomText
                  size='18px'
                  color={AgentColorPallette.black}
                  weight={800}
                >
                  {formatMoney(packageDetail.total_bill, 0)}
                </CustomText>
                <CustomText weight={800} color={AgentColorPallette.fontSecondary}>/ {LANG_STRINGS.year}</CustomText>
              </div>
              <Button className='offer-btn' onClick={this.handleBuy}>
                {btnText}
              </Button>
            </Row>
          </BottomActionContainerStyle>
        </AdiraPkgDetailsStyle>
      </CircularLoader>
    )
  }
}

export default connect(
  (state) => ({
    packageDetail: state.Policy.packageDetail,
    packageDetailLoading: state.Loading.GET_PACKAGE_DETAIL
  }),
  {
    getPackageDetail
  }
)(AdiraPackageDetails)
