import { Component } from 'react'
import AdiraPackageDetails from '../../CommonContainer/AdiraPackageDetails'
import { Container } from '../../../components'
import { LANG_STRINGS } from '../../../lang'
import { getParamsFromUri } from '../../../helpers/utility'

class MotorPkgDetail extends Component {
  constructor (props) {
    super(props)
    this.productCode = getParamsFromUri.call(this, 'productCode')
  }

  handleToShareInsurance = () => {
    // this is handle to share the insurance and move the user to share screen
    this.props.history.push({
      pathname: `/${this.productCode}/sharing`
    })
  }

  render () {
    return (
      <Container title={LANG_STRINGS.motorCycleInsurance} hideBottomTabs>
        <AdiraPackageDetails
          productCode={this.productCode}
          btnText={LANG_STRINGS.offerInsurance}
          onInsuranceBtnClick={this.handleToShareInsurance}
        />
      </Container>
    )
  }
}

export default MotorPkgDetail
