import { Component } from 'react'
import PropTypes from 'prop-types'
import { ExpandStyle, ExpandBodyStyle } from './index.style'
import { Row } from '../../commonStyle/index.style'
import CustomText from '../CustomText'
import { AgentColorPallette } from '../../configs/colorPallete'

class Expand extends Component {
  static propTypes = {
    isHideIcon: PropTypes.bool,
    expand: PropTypes.bool,
    onExpand: PropTypes.func,
    title: PropTypes.string,
    headerColor: PropTypes.string,
    titleColor: PropTypes.string,
    name: PropTypes.string
  }

  state = {
    isExpand: this.props.expand || false
  }

  handleExpand = () => {
    if (this.props.onExpand) {
      this.props.onExpand()
    } else {
      this.setState(prevState => ({
        isExpand: !prevState.isExpand
      }))
    }
  }

  render () {
    const {
      title, isHideIcon, children, imgUrl,
      name, className, expand, headerColor, titleColor
    } = this.props
    const { isExpand } = this.state
    let open = isExpand
    if (expand === false) {
      open = expand
    } else if (expand) {
      open = expand
    }

    return (
      <ExpandStyle
        expand={open}
        key={name}
        className={className}
        headerColor={headerColor}
        titleColor={titleColor}
      >
        <Row
          justify='space-between'
          align='center'
          onClick={this.handleExpand}
          className='expand-header'
        >
          <Row align='center'>
            {!!imgUrl && <img className='expand-img' src={imgUrl} alt='' />}
            <CustomText size='16px' weight={800} color={titleColor || AgentColorPallette.black}>
              {title}
            </CustomText>
          </Row>
          {
            !isHideIcon &&
              <div className='up-down'>
                <i className={`fas ${open ? 'fa-angle-up' : 'fa-angle-down'}`} />
              </div>
          }
        </Row>
        {
          open && (
            <ExpandBodyStyle expand={open}>
              {children}
            </ExpandBodyStyle>
          )
        }
      </ExpandStyle>
    )
  }
}

export default Expand
